mapper.select:
SELECT id, provider_id, model_code, model_name, upstream_model_id, api_protocol, capability_type, tenant_id, owner_user_id, status, lock_version, update_time FROM blade_ai_model_config WHERE is_deleted = 0
AND provider_id = #{param.providerId}
AND tenant_id = #{param.tenantId}
AND owner_user_id = #{param.ownerUserId}
AND model_code LIKE CONCAT('%', #{param.modelCode}, '%')
AND model_name LIKE CONCAT('%', #{param.modelName}, '%')
AND status = #{param.status}
ORDER BY update_time DESC, id DESC
